package com.smartserve.service;
import java.util.Locale;
import com.smartserve.dto.AuthDtos.*; import com.smartserve.entity.User; import com.smartserve.enums.Role; import com.smartserve.repository.UserRepository; import com.smartserve.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public AuthResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.findByEmail(email).isPresent())throw new IllegalArgumentException("Email already registered");User u=new User();u.setName(r.name());u.setEmail(email);u.setPassword(encoder.encode(r.password()));u.setPhone(r.phone());u.setAddress(r.address());u.setRole(Role.CUSTOMER);users.save(u);return new AuthResponse(jwt.generate(u.getEmail()),u.getId(),u.getName(),u.getEmail(),u.getRole().name());} public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email().trim().toLowerCase(Locale.ROOT)).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!u.isEnabled())throw new IllegalArgumentException("Account is disabled");if(!encoder.matches(r.password(),u.getPassword()))throw new IllegalArgumentException("Invalid email or password");return new AuthResponse(jwt.generate(u.getEmail()),u.getId(),u.getName(),u.getEmail(),u.getRole().name());} }
